\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\pagestyle{empty}

% ── Dark Mode Color Theme ──
\definecolor{bgdeep}{HTML}{0D1117}
\definecolor{bgcard}{HTML}{161B22}
\definecolor{bgcardalt}{HTML}{1C2333}
\definecolor{bgheader}{HTML}{21262D}
\definecolor{accentblue}{HTML}{58A6FF}
\definecolor{accentcyan}{HTML}{39D2E3}
\definecolor{gaingreen}{HTML}{3FB950}
\definecolor{lossred}{HTML}{F85149}
\definecolor{textwhite}{HTML}{F0F6FC}
\definecolor{textlight}{HTML}{C9D1D9}
\definecolor{textmuted}{HTML}{8B949E}
\definecolor{textdim}{HTML}{6E7681}
\definecolor{bordergray}{HTML}{30363D}
\definecolor{titlebg}{HTML}{0D1117}
\definecolor{statbg}{HTML}{161B22}
\definecolor{tabheader}{HTML}{21262D}
\definecolor{tabrow1}{HTML}{161B22}
\definecolor{tabrow2}{HTML}{0D1117}
\definecolor{goldaccent}{HTML}{E3B341}
\definecolor{purpleaccent}{HTML}{BC8CFF}
\definecolor{orangeaccent}{HTML}{F0883E}
\definecolor{pythonblue}{HTML}{3572A5}
\definecolor{cppblue}{HTML}{6295CB}
\definecolor{javaorange}{HTML}{E76F00}

\pagecolor{bgdeep}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accentblue}$\bullet$}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textmuted}\textit{#3}}\vspace{2mm}%
}

% ── Share bar macro ──
\newcommand{\sharebar}[2]{%
  \begin{tikzpicture}[baseline=-0.5ex]
    \fill[bgheader,rounded corners=2pt] (0,0) rectangle (5.2,0.45);
    \fill[#2,rounded corners=2pt] (0,0) rectangle ({5.2*#1/36.21},0.45);
  \end{tikzpicture}%
}

% ── Trend arrow macros ──
\newcommand{\trup}[1]{{\color{gaingreen}\fontsize{30}{38}\selectfont$\blacktriangle$ \textbf{+#1\%}}}
\newcommand{\trdown}[1]{{\color{lossred}\fontsize{30}{38}\selectfont$\blacktriangledown$ \textbf{#1\%}}}
\newcommand{\trflat}[1]{{\color{textmuted}\fontsize{30}{38}\selectfont$\bullet$ \textbf{#1\%}}}

% ── Card styles for dark mode ──
\tcbset{
  darkcard/.style={
    enhanced, arc=4pt, boxrule=1pt, colframe=bordergray,
    colback=bgcard,
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accentblue},
    coltitle=accentblue, colbacktitle=bgheader,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.3, shadow xshift=2mm, shadow yshift=-2mm},
  },
  greencard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=bgcard,
    borderline west={5pt}{0pt}{gaingreen},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{gaingreen},
    coltitle=gaingreen, colbacktitle=bgheader,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.3, shadow xshift=2mm, shadow yshift=-2mm},
  },
  redcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=bgcard,
    borderline west={5pt}{0pt}{lossred},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{lossred},
    coltitle=lossred, colbacktitle=bgheader,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.3, shadow xshift=2mm, shadow yshift=-2mm},
  },
  bluecard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=bgcard,
    borderline west={5pt}{0pt}{accentblue},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accentblue},
    coltitle=accentblue, colbacktitle=bgheader,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.3, shadow xshift=2mm, shadow yshift=-2mm},
  },
  accentcard/.style={
    enhanced, arc=4pt, boxrule=0pt,
    colback=accentblue!12!bgdeep,
    borderline west={6pt}{0pt}{accentblue},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=accentblue!80!black,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.3, shadow xshift=2mm, shadow yshift=-2mm},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=4mm},
]

% ══════════════════════════════════════
% TITLE BAR
% ══════════════════════════════════════
\posterbox[
  enhanced, colback=bgdeep, colframe=bgdeep, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=50pt, right=50pt, top=20pt, bottom=10pt,
  halign=center, valign=center,
  borderline south={3pt}{0pt}{accentblue},
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{28}{34}\selectfont\color{accentblue}\texttt{// APRIL 2026 DATA REPORT}}\\[14pt]
  {\fontsize{78}{94}\selectfont\bfseries\color{textwhite} PYPL Programming Language}\\[6pt]
  {\fontsize{78}{94}\selectfont\bfseries\color{textwhite} Popularity Index}\\[16pt]
  {\fontsize{30}{38}\selectfont\color{textmuted} Which programming languages are developers searching to learn? \quad$|$\quad Data: Google Trends worldwide tutorial searches}
}

% ══════════════════════════════════════
% STAT CALLOUTS — Three headline metrics
% ══════════════════════════════════════
\posterbox[
  enhanced, colback=bgdeep, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=10pt, bottom=10pt,
  valign=center,
  borderline south={2pt}{0pt}{bordergray},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \begin{tcolorbox}[enhanced, arc=6pt, boxrule=2pt, colframe=pythonblue,
      colback=pythonblue!10!bgdeep, left=12pt, right=12pt, top=12pt, bottom=12pt,
      halign=center, drop shadow={opacity=0.3}]
      {\fontsize{24}{30}\selectfont\color{textmuted}\texttt{\#1 WORLDWIDE}}\\[6pt]
      {\fontsize{80}{96}\selectfont\bfseries\color{textwhite} 36.21\%}\\[4pt]
      {\fontsize{36}{44}\selectfont\bfseries\color{pythonblue} Python}\\[6pt]
      {\color{gaingreen}\fontsize{30}{36}\selectfont $\blacktriangle$ \textbf{+5.7\%} YoY}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \begin{tcolorbox}[enhanced, arc=6pt, boxrule=2pt, colframe=gaingreen,
      colback=gaingreen!8!bgdeep, left=12pt, right=12pt, top=12pt, bottom=12pt,
      halign=center, drop shadow={opacity=0.3}]
      {\fontsize{24}{30}\selectfont\color{textmuted}\texttt{\#2 BIGGEST GAINER}}\\[6pt]
      {\fontsize{80}{96}\selectfont\bfseries\color{textwhite} 13.21\%}\\[4pt]
      {\fontsize{36}{44}\selectfont\bfseries\color{cppblue} C/C++}\\[6pt]
      {\color{gaingreen}\fontsize{30}{36}\selectfont $\blacktriangle$ \textbf{+6.2\%} YoY}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \begin{tcolorbox}[enhanced, arc=6pt, boxrule=2pt, colframe=lossred,
      colback=lossred!8!bgdeep, left=12pt, right=12pt, top=12pt, bottom=12pt,
      halign=center, drop shadow={opacity=0.3}]
      {\fontsize{24}{30}\selectfont\color{textmuted}\texttt{\#3 STEEPEST DECLINE}}\\[6pt]
      {\fontsize{80}{96}\selectfont\bfseries\color{textwhite} 10.01\%}\\[4pt]
      {\fontsize{36}{44}\selectfont\bfseries\color{javaorange} Java}\\[6pt]
      {\color{lossred}\fontsize{30}{36}\selectfont $\blacktriangledown$ \textbf{$-$5.4\%} YoY}
    \end{tcolorbox}
  \end{minipage}
}

% ══════════════════════════════════════
% TOP 10 TABLE — CENTERPIECE (span all 3 columns)
% ══════════════════════════════════════
\posterbox[
  darkcard, title={Top 10 Languages by Tutorial Search Share}
]{name=table, column=1, span=3, between=row5 and row13}{
  \fontsize{32}{42}\selectfont\color{textlight}
  \centering
  \renewcommand{\arraystretch}{2.0}
  \begin{tabular}{@{\hspace{10pt}}c @{\hspace{20pt}} l @{\hspace{26pt}} r @{\hspace{20pt}} l @{\hspace{20pt}} r @{\hspace{10pt}}}
    \rowcolor{tabheader}
    {\fontsize{28}{34}\selectfont\color{textmuted}\textbf{RANK}} &
    {\fontsize{28}{34}\selectfont\color{textmuted}\textbf{LANGUAGE}} &
    {\fontsize{28}{34}\selectfont\color{textmuted}\textbf{SHARE}} &
    {\fontsize{28}{34}\selectfont\color{textmuted}\textbf{VISUAL}} &
    {\fontsize{28}{34}\selectfont\color{textmuted}\textbf{1-YEAR TREND}} \\
    %
    \rowcolor{tabrow1}
    {\fontsize{38}{46}\selectfont\color{goldaccent}\textbf{1}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{Python}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{36.21\%}} &
    \sharebar{36.21}{pythonblue} &
    \trup{5.7} \\
    %
    \rowcolor{tabrow2}
    {\fontsize{38}{46}\selectfont\color{textlight}\textbf{2}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{C/C++}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{13.21\%}} &
    \sharebar{13.21}{cppblue} &
    \trup{6.2} \\
    %
    \rowcolor{tabrow1}
    {\fontsize{38}{46}\selectfont\color{textlight}\textbf{3}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{Java}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{10.01\%}} &
    \sharebar{10.01}{javaorange} &
    \trdown{-5.4} \\
    %
    \rowcolor{tabrow2}
    {\fontsize{38}{46}\selectfont\color{textlight}\textbf{4}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{R}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{6.17\%}} &
    \sharebar{6.17}{accentblue} &
    \trup{1.6} \\
    %
    \rowcolor{tabrow1}
    {\fontsize{38}{46}\selectfont\color{textlight}\textbf{5}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{JavaScript}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{5.07\%}} &
    \sharebar{5.07}{orangeaccent} &
    \trdown{-3.0} \\
    %
    \rowcolor{tabrow2}
    {\fontsize{38}{46}\selectfont\color{textlight}\textbf{6}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{Swift}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{3.15\%}} &
    \sharebar{3.15}{orangeaccent} &
    \trup{0.8} \\
    %
    \rowcolor{tabrow1}
    {\fontsize{38}{46}\selectfont\color{textlight}\textbf{7}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{C\#}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{3.00\%}} &
    \sharebar{3.00}{purpleaccent} &
    \trdown{-3.0} \\
    %
    \rowcolor{tabrow2}
    {\fontsize{38}{46}\selectfont\color{textlight}\textbf{8}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{Rust}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{2.98\%}} &
    \sharebar{2.98}{orangeaccent} &
    \trflat{-0.1} \\
    %
    \rowcolor{tabrow1}
    {\fontsize{38}{46}\selectfont\color{textlight}\textbf{9}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{PHP}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{2.96\%}} &
    \sharebar{2.96}{purpleaccent} &
    \trdown{-0.7} \\
    %
    \rowcolor{tabrow2}
    {\fontsize{38}{46}\selectfont\color{textlight}\textbf{10}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{Objective-C}} &
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{2.57\%}} &
    \sharebar{2.57}{textmuted} &
    \trflat{+0.1} \\
  \end{tabular}

  \vspace{14pt}
  {\fontsize{28}{36}\selectfont\color{textmuted}\textit{Python alone accounts for more than a third of all tutorial searches --- nearly 3$\times$ its closest competitor.}}
}

% ══════════════════════════════════════
% ROW 3: Gainers | Losers | 5-Year Trends
% ══════════════════════════════════════

% Biggest Gainers
\posterbox[
  greencard, title={Biggest Gainers}
]{name=gainers, column=1, between=row13 and row17}{
  \fontsize{32}{42}\selectfont\color{textlight}
  \vspace{4pt}

  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=0pt, colback=gaingreen!12!bgdeep,
    left=12pt, right=12pt, top=8pt, bottom=8pt]
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{C/C++}}\hfill
    {\fontsize{40}{48}\selectfont\color{gaingreen}\textbf{+6.2\%}}\\[2pt]
    {\fontsize{26}{32}\selectfont\color{textmuted} Surged to \#2, largest 1-year gain}
  \end{tcolorbox}
  \vspace{6pt}

  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=0pt, colback=gaingreen!8!bgdeep,
    left=12pt, right=12pt, top=8pt, bottom=8pt]
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{Python}}\hfill
    {\fontsize{40}{48}\selectfont\color{gaingreen}\textbf{+5.7\%}}\\[2pt]
    {\fontsize{26}{32}\selectfont\color{textmuted} Extends dominant \#1 position}
  \end{tcolorbox}
  \vspace{6pt}

  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=0pt, colback=gaingreen!6!bgdeep,
    left=12pt, right=12pt, top=8pt, bottom=8pt]
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{R}}\hfill
    {\fontsize{40}{48}\selectfont\color{gaingreen}\textbf{+1.6\%}}\\[2pt]
    {\fontsize{26}{32}\selectfont\color{textmuted} Data-science demand continues}
  \end{tcolorbox}
  \vspace{6pt}

  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=0pt, colback=gaingreen!5!bgdeep,
    left=12pt, right=12pt, top=8pt, bottom=8pt]
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{Ada}}\hfill
    {\fontsize{40}{48}\selectfont\color{gaingreen}\textbf{+1.1\%}}\\[2pt]
    {\fontsize{26}{32}\selectfont\color{textmuted} Growth in safety-critical domains}
  \end{tcolorbox}
}

% Biggest Losers
\posterbox[
  redcard, title={Biggest Losers}
]{name=losers, column=2, between=row13 and row17}{
  \fontsize{32}{42}\selectfont\color{textlight}
  \vspace{4pt}

  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=0pt, colback=lossred!12!bgdeep,
    left=12pt, right=12pt, top=8pt, bottom=8pt]
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{Java}}\hfill
    {\fontsize{40}{48}\selectfont\color{lossred}\textbf{$-$5.4\%}}\\[2pt]
    {\fontsize{26}{32}\selectfont\color{textmuted} Steepest single-year decline}
  \end{tcolorbox}
  \vspace{6pt}

  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=0pt, colback=lossred!8!bgdeep,
    left=12pt, right=12pt, top=8pt, bottom=8pt]
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{JavaScript}}\hfill
    {\fontsize{40}{48}\selectfont\color{lossred}\textbf{$-$3.0\%}}\\[2pt]
    {\fontsize{26}{32}\selectfont\color{textmuted} Under pressure, dropped to \#5}
  \end{tcolorbox}
  \vspace{6pt}

  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=0pt, colback=lossred!6!bgdeep,
    left=12pt, right=12pt, top=8pt, bottom=8pt]
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{C\#}}\hfill
    {\fontsize{40}{48}\selectfont\color{lossred}\textbf{$-$3.0\%}}\\[2pt]
    {\fontsize{26}{32}\selectfont\color{textmuted} Slipped to \#7, steady decline}
  \end{tcolorbox}
  \vspace{6pt}

  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=0pt, colback=lossred!4!bgdeep,
    left=12pt, right=12pt, top=8pt, bottom=8pt]
    {\fontsize{34}{42}\selectfont\color{textwhite}\textbf{Go}}\hfill
    {\fontsize{40}{48}\selectfont\color{lossred}\textbf{$-$1.3\%}}\\[2pt]
    {\fontsize{26}{32}\selectfont\color{textmuted} Notable drop despite cloud popularity}
  \end{tcolorbox}
}

