    {\color{textwhite} Zig} & {\color{textwhite} 0.24\%} & {\color{textmuted} $\bullet$ +0.0\%} \\
  \end{tabular}
}

% Key Takeaways
\posterbox[
  accentcard, title={Key Takeaways}
]{name=takeaways, column=2, between=row17 and row20}{
  \fontsize{30}{40}\selectfont\color{textwhite}
  \begin{itemize}[label={\color{accentcyan}$\blacktriangleright$}, itemsep=10pt]
    \item \textbf{Python unchallenged at \#1} with 36\% share, still growing
    \item \textbf{C/C++ is the breakout story} --- largest gains in 1-year and 5-year windows
    \item \textbf{Java's long slide continues} --- 7 points lost over 5 years
    \item \textbf{JS and C\# under pressure} --- each dropped 3 points year-over-year
  \end{itemize}
}

% Methodology
\posterbox[
  darkcard, title={How PYPL Works}
]{name=methodology, column=3, between=row17 and row20}{
  \fontsize{28}{38}\selectfont\color{textmuted}
  PYPL measures \textbf{\color{textlight}Google Trends tutorial search frequency} worldwide. Each language's share is normalized to 100\% and smoothed over a 6-month window.

  \vspace{8pt}
  Unlike TIOBE (counts existing web pages), PYPL captures \textbf{\color{accentblue}learning intent} --- a \textit{leading indicator} of adoption.

  \vspace{10pt}
  {\fontsize{24}{30}\selectfont\color{textdim} Data: PYPL / Google Trends, April 2026\\
  \copyright\ Pierre Carbonnelle, CC BY 3.0\\
  30 languages tracked worldwide}
}

