      halign=center]
      {\fontsize{22}{28}\selectfont\color{textmuted}\texttt{\#2 BIGGEST GAINER}}\\[8pt]
      {\fontsize{76}{92}\selectfont\bfseries\color{textwhite} 13.21\%}\\[6pt]
      {\fontsize{36}{44}\selectfont\bfseries\color{cppblue} C/C++}\\[6pt]
      {\color{gaingreen}\fontsize{28}{34}\selectfont $\blacktriangle$ \textbf{+6.2\%} YoY}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \begin{tcolorbox}[enhanced, arc=6pt, boxrule=2pt, colframe=lossred,
      colback=lossred!8!bgdeep, left=12pt, right=12pt, top=14pt, bottom=14pt,
      halign=center]
      {\fontsize{22}{28}\selectfont\color{textmuted}\texttt{\#3 STEEPEST DECLINE}}\\[8pt]
      {\fontsize{76}{92}\selectfont\bfseries\color{textwhite} 10.01\%}\\[6pt]
      {\fontsize{36}{44}\selectfont\bfseries\color{javaorange} Java}\\[6pt]
      {\color{lossred}\fontsize{28}{34}\selectfont $\blacktriangledown$ \textbf{$-$5.4\%} YoY}
    \end{tcolorbox}
  \end{minipage}
}

% ══════════════════════════════════════
% TOP 10 TABLE — CENTERPIECE (rows 5-14, span 3)
% ══════════════════════════════════════
